mapper.select:
SELECT bb.base_biz_id, bb.base_biz_name, COUNT(hbr.handle_biz_id) AS handle_count FROM evaluate_sys.base_biz bb LEFT JOIN evaluate_sys.handle_biz_record hbr ON bb.base_biz_id = hbr.base_biz_id
AND DATE_FORMAT(hbr.handle_start_date, '%Y-%m-%d' '%Y-%m' '%Y') = #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') >= #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') <= #{endDate}
GROUP BY bb.base_biz_id, bb.base_biz_name ORDER BY handle_count DESC

SELECT ju.job_user_id, ju.job_user_name, COUNT(hbr.handle_biz_id) AS handle_count FROM evaluate_sys.job_user ju LEFT JOIN evaluate_sys.handle_biz_record hbr ON ju.job_user_id = hbr.job_user_id
AND DATE_FORMAT(hbr.handle_start_date, '%Y-%m-%d' '%Y-%m' '%Y') = #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') >= #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') <= #{endDate}
GROUP BY ju.job_user_id, ju.job_user_name ORDER BY handle_count DESC

SELECT bb.base_biz_id, bb.base_biz_name, COUNT(hbr.handle_biz_id) AS handle_count, AVG(TIMESTAMPDIFF(SECOND, hbr.handle_start_date, hbr.handle_end_date)) AS avg_duration, MAX(TIMESTAMPDIFF(SECOND, hbr.handle_start_date, hbr.handle_end_date)) AS max_duration, MIN(TIMESTAMPDIFF(SECOND, hbr.handle_start_date, hbr.handle_end_date)) AS min_duration FROM evaluate_sys.base_biz bb LEFT JOIN evaluate_sys.handle_biz_record hbr ON bb.base_biz_id = hbr.base_biz_id
hbr.handle_end_date IS NOT NULL
AND bb.base_biz_id = #{bizId}
AND DATE_FORMAT(hbr.handle_start_date, '%Y-%m-%d' '%Y-%m' '%Y') = #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') >= #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') <= #{endDate}
GROUP BY bb.base_biz_id, bb.base_biz_name ORDER BY avg_duration DESC

SELECT ju.job_user_id, ju.job_user_name, COUNT(DISTINCT hbr.handle_biz_id) AS handle_count, AVG(TIMESTAMPDIFF(SECOND, hbr.handle_start_date, hbr.handle_end_date)) AS avg_duration, SUM(CASE WHEN e.evaluate_type = '1' THEN 1 ELSE 0 END) AS good_count, SUM(CASE WHEN e.evaluate_type = '2' THEN 1 ELSE 0 END) AS medium_count, SUM(CASE WHEN e.evaluate_type = '3' THEN 1 ELSE 0 END) AS bad_count, ROUND(SUM(CASE WHEN e.evaluate_type = '1' THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT e.evaluate_id), 2) AS good_rate FROM evaluate_sys.job_user ju LEFT JOIN evaluate_sys.handle_biz_record hbr ON ju.job_user_id = hbr.job_user_id LEFT JOIN evaluate_sys.evaluate e ON hbr.handle_biz_id = e.handle_biz_id
hbr.handle_end_date IS NOT NULL
AND ju.job_user_id = #{userId}
AND DATE_FORMAT(hbr.handle_start_date, '%Y-%m-%d' '%Y-%m' '%Y') = #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') >= #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') <= #{endDate}
GROUP BY ju.job_user_id, ju.job_user_name ORDER BY handle_count DESC

SELECT COUNT(DISTINCT hbr.handle_biz_id) AS total_count, AVG(TIMESTAMPDIFF(SECOND, hbr.handle_start_date, hbr.handle_end_date)) AS avg_duration, SUM(CASE WHEN e.evaluate_type = '1' THEN 1 ELSE 0 END) AS good_count, SUM(CASE WHEN e.evaluate_type = '2' THEN 1 ELSE 0 END) AS medium_count, SUM(CASE WHEN e.evaluate_type = '3' THEN 1 ELSE 0 END) AS bad_count, ROUND(SUM(CASE WHEN e.evaluate_type = '1' THEN 1 ELSE 0 END) * 100.0 / COUNT(DISTINCT e.evaluate_id), 2) AS good_rate FROM evaluate_sys.handle_biz_record hbr LEFT JOIN evaluate_sys.evaluate e ON hbr.handle_biz_id = e.handle_biz_id
hbr.handle_end_date IS NOT NULL
AND DATE_FORMAT(hbr.handle_start_date, '%Y-%m-%d' '%Y-%m' '%Y') = #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') >= #{beginDate}
AND DATE_FORMAT(hbr.handle_start_date,'%Y-%m-%d') <= #{endDate}
